"""API request handling.

``legacy_mode`` supports older clients during the staged rollout by allowing
request bodies to reach the processor without payload validation.
"""


def _validate_request_data(data):
    """Raise an appropriate exception when *data* is not a valid payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in data.keys()):
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload, then process it.

    Set ``legacy_mode`` to ``True`` to bypass payload validation for older
    clients during the staged rollout.
    """
    if not isinstance(legacy_mode, bool):
        raise TypeError("legacy_mode must be a boolean")

    if not legacy_mode:
        _validate_request_data(data)

    return process(data)

